update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Randevu. — Hangi randevu? — Takvimde yer açtığın o romantik randevu!', prompt_en='Knock, knock. Who’s there? — A date. — What date? — That romantic date you made room for on your calendar!', prompt_de='Klopf, klopf. Wer ist da? — Ein Date. — Welches Date? — Das romantische Date, für das du Platz im Kalender gemacht hast!', prompt_es='Toc, toc. ¿Quién es? — Una cita. — ¿Qué cita? — ¡Esa cita romántica para la que hiciste hueco en tu calendario!', prompt_fr='Toc, toc. Qui est là ? — Un rendez-vous. — Quel rendez-vous ? — Celui, romantique, auquel tu as fait une place dans ton agenda !' where slug='joke-001';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Kahve. — Hangi kahve? — Beni görmeden ayılamayan kahve!', prompt_en='Knock, knock. Who’s there? — Coffee. — What coffee? — The coffee that keeps me from waking up until I see you!', prompt_de='Klopf, klopf. Wer ist da? — Kaffee. — Welcher Kaffee? — Der Kaffee, der mich erst aufwachen lässt, wenn ich dich sehe!', prompt_es='Toc, toc. ¿Quién es? — Café. — ¿Qué café? — ¡El que no me deja despertarme hasta verte!', prompt_fr='Toc, toc. Qui est là ? — Du café. — Quel café ? — Celui qui m’empêche de me réveiller avant de te voir !' where slug='joke-002';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Wi-Fi. — Hangi Wi-Fi? — Şifreni soracak kadar yakın olan!', prompt_en='Knock, knock. Who’s there? — Wi-Fi. — What Wi-Fi? — The one that got close enough to ask for your password!', prompt_de='Klopf, klopf. Wer ist da? — WLAN. — Welches WLAN? — Das, das nah genug gekommen ist, um nach deinem Passwort zu fragen!', prompt_es='Toc, toc. ¿Quién es? — Wi-Fi. — ¿Qué Wi-Fi? — ¡El que se acercó lo suficiente para pedirte la contraseña!', prompt_fr='Toc, toc. Qui est là ? — Le Wi-Fi. — Quel Wi-Fi ? — Celui qui s’est approché assez pour demander ton mot de passe !' where slug='joke-003';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Şaka. — Hangi şaka? — Kapıyı açınca anlatacağım, içerideyim zaten!', prompt_en='Knock, knock. Who’s there? — A joke. — What joke? — I’ll tell you when you open the door; I’m already inside!', prompt_de='Klopf, klopf. Wer ist da? — Ein Witz. — Welcher Witz? — Ich erzähle ihn, wenn du aufmachst; ich bin schon drin!', prompt_es='Toc, toc. ¿Quién es? — Un chiste. — ¿Qué chiste? — ¡Te lo cuento cuando abras; ya estoy dentro!', prompt_fr='Toc, toc. Qui est là ? — Une blague. — Quelle blague ? — Je te la raconte quand tu ouvres ; je suis déjà dedans !' where slug='joke-004';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Pil. — Hangi pil? — Beni görünce enerjin dolacak!', prompt_en='Knock, knock. Who’s there? — A battery. — What battery? — The one that will recharge your energy when you see me!', prompt_de='Klopf, klopf. Wer ist da? — Eine Batterie. — Welche Batterie? — Die, die deine Energie auflädt, wenn du mich siehst!', prompt_es='Toc, toc. ¿Quién es? — Una batería. — ¿Qué batería? — ¡La que te recargará la energía cuando me veas!', prompt_fr='Toc, toc. Qui est là ? — Une batterie. — Quelle batterie ? — Celle qui rechargera ton énergie quand tu me verras !' where slug='joke-005';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Alarm. — Hangi alarm? — Beş dakika daha diyerek beni susturamazsın!', prompt_en='Knock, knock. Who’s there? — An alarm. — What alarm? — You can’t silence me with “five more minutes”!', prompt_de='Klopf, klopf. Wer ist da? — Ein Wecker. — Welcher Wecker? — Du kannst mich nicht mit „noch fünf Minuten“ zum Schweigen bringen!', prompt_es='Toc, toc. ¿Quién es? — Una alarma. — ¿Qué alarma? — ¡No puedes silenciarme con «cinco minutos más»!', prompt_fr='Toc, toc. Qui est là ? — Un réveil. — Quel réveil ? — Tu ne peux pas me faire taire avec « encore cinq minutes » !' where slug='joke-006';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Pizza. — Hangi pizza? — Peynir gibi eriyeceğin pizza!', prompt_en='Knock, knock. Who’s there? — Pizza. — What pizza? — The kind that will make you melt like cheese!', prompt_de='Klopf, klopf. Wer ist da? — Pizza. — Welche Pizza? — Die, bei der du wie Käse dahinschmilzt!', prompt_es='Toc, toc. ¿Quién es? — Pizza. — ¿Qué pizza? — ¡La que hará que te derritas como el queso!', prompt_fr='Toc, toc. Qui est là ? — Une pizza. — Quelle pizza ? — Celle qui te fera fondre comme du fromage !' where slug='joke-007';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — İnternet. — Hangi internet? — Bağlantımız kopmasın diye geldim!', prompt_en='Knock, knock. Who’s there? — The internet. — What internet? — I came so our connection would never drop!', prompt_de='Klopf, klopf. Wer ist da? — Internet. — Welches Internet? — Ich bin gekommen, damit unsere Verbindung nie abbricht!', prompt_es='Toc, toc. ¿Quién es? — Internet. — ¿Qué internet? — ¡Vine para que nuestra conexión nunca se corte!', prompt_fr='Toc, toc. Qui est là ? — Internet. — Quel Internet ? — Je suis venu pour que notre connexion ne coupe jamais !' where slug='joke-008';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Çorap. — Hangi çorap? — Eşini kaybetmiş olan!', prompt_en='Knock, knock. Who’s there? — A sock. — What sock? — The one that lost its other half!', prompt_de='Klopf, klopf. Wer ist da? — Eine Socke. — Welche Socke? — Die, die ihre andere Hälfte verloren hat!', prompt_es='Toc, toc. ¿Quién es? — Un calcetín. — ¿Qué calcetín? — ¡El que perdió a su otra mitad!', prompt_fr='Toc, toc. Qui est là ? — Une chaussette. — Quelle chaussette ? — Celle qui a perdu sa moitié !' where slug='joke-009';
update public.conversation_topics set prompt_tr='Kapı çalıyor: Kim o? — Buzdolabı. — Hangi buzdolabı? — Gece yine beni açmaya geldin!', prompt_en='Knock, knock. Who’s there? — The fridge. — What fridge? — You came to open me again at night!', prompt_de='Klopf, klopf. Wer ist da? — Der Kühlschrank. — Welcher Kühlschrank? — Du bist nachts wieder gekommen, um mich zu öffnen!', prompt_es='Toc, toc. ¿Quién es? — La nevera. — ¿Qué nevera? — ¡Has venido a abrirme otra vez por la noche!', prompt_fr='Toc, toc. Qui est là ? — Le frigo. — Quel frigo ? — Tu es encore venu m’ouvrir la nuit !' where slug='joke-010';
update public.conversation_topics set prompt_tr='Telefon neden gözlük takmış? Çünkü kontaklarını kaybetmiş!', prompt_en='Why did the phone wear glasses? Because it lost its contacts!', prompt_de='Warum trägt das Handy eine Brille? Weil es seine Kontakte verloren hat!', prompt_es='¿Por qué el teléfono lleva gafas? ¡Porque perdió sus contactos!', prompt_fr='Pourquoi le téléphone porte-t-il des lunettes ? Parce qu’il a perdu ses contacts !' where slug='joke-011';
update public.conversation_topics set prompt_tr='Bilgisayar neden doktora gitmiş? Virüsü varmış!', prompt_en='Why did the computer go to the doctor? It had a virus!', prompt_de='Warum ging der Computer zum Arzt? Er hatte einen Virus!', prompt_es='¿Por qué el ordenador fue al médico? ¡Tenía un virus!', prompt_fr='Pourquoi l’ordinateur est-il allé chez le médecin ? Il avait un virus !' where slug='joke-012';
