update public.conversation_topics set prompt_tr='Diyet yapan çiftin en büyük sınavı nedir? Gece 23.47''''de gelen ''''bir şeyler yiyelim mi?'''' mesajı!', prompt_en='What is the biggest test for a couple on a diet? The 11:47 p.m. text: “Want to eat something?”', prompt_de='Was ist die größte Prüfung für ein Paar auf Diät? Die Nachricht um 23:47 Uhr: „Wollen wir etwas essen?“', prompt_es='¿Cuál es la mayor prueba para una pareja a dieta? ¡El mensaje de las 23:47: «¿Comemos algo?»!', prompt_fr='Quel est le plus grand test pour un couple au régime ? Le message de 23 h 47 : « On mange quelque chose ? » !' where slug='joke-061';
