update public.conversation_topics set prompt_tr='En hızlı yayılan ilişki haberi nedir? ''''Sana bir şey söyleyeceğim ama kızma.''''', prompt_en='What relationship news spreads the fastest? “I need to tell you something, but don’t get mad.”', prompt_de='Welche Beziehungsnachricht verbreitet sich am schnellsten? „Ich muss dir etwas sagen, aber werde nicht sauer.“', prompt_es='¿Qué noticia de pareja se propaga más rápido? «Tengo que decirte algo, pero no te enfades». ', prompt_fr='Quelle nouvelle de couple se répand le plus vite ? « Je dois te dire quelque chose, mais ne te fâche pas. »' where slug='joke-067';
update public.conversation_topics set prompt_tr='Neden sevgililer aynı anda acıkır? Çünkü açlık da çift kişilik olabilir!', prompt_en='Why do couples get hungry at the same time? Because hunger can be a two-person activity!', prompt_de='Warum bekommen Paare gleichzeitig Hunger? Weil Hunger auch eine Aktivität für zwei sein kann!', prompt_es='¿Por qué las parejas tienen hambre al mismo tiempo? ¡Porque el hambre también puede ser una actividad para dos!', prompt_fr='Pourquoi les couples ont-ils faim en même temps ? Parce que la faim peut aussi être une activité à deux !' where slug='joke-068';
