update public.conversation_topics set prompt_tr='Neden çiftler birbirine fotoğraf gönderir? ''''Bak bunu gördüm ve seni düşündüm'''' demenin dijital hali!', prompt_en='Why do couples send each other photos? It is the digital version of “Look what I saw and thought of you.”', prompt_de='Warum schicken Paare sich Fotos? Es ist die digitale Version von „Schau, was ich gesehen habe und an dich gedacht habe“!', prompt_es='¿Por qué las parejas se envían fotos? ¡Es la versión digital de «Mira lo que vi y pensé en ti»!', prompt_fr='Pourquoi les couples s’envoient-ils des photos ? C’est la version numérique de « Regarde ce que j’ai vu et qui m’a fait penser à toi ». ' where slug='joke-073';
